/**
 * The course form in four steps (Basics, Catalog details, Certificate rules, Advanced) with a step bar
 * and a live preview of the course's catalog card. Presentation only: Moodle's own fieldsets are moved
 * into the steps inside the same form, so every field is still posted and saved as before.
 *
 * @module     theme_hikmah/courseform
 * @copyright  2026 Hikmah Institute
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

import Templates from 'core/templates';

const BASICS = ['id_general', 'id_descriptionhdr'];

/**
 * The fieldset holding this element.
 *
 * @param {string} selector
 * @returns {HTMLElement|null}
 */
const fieldsetOf = (selector) => {
    const el = document.querySelector(selector);
    return el ? el.closest('fieldset') : null;
};

/**
 * Text of a select's chosen option ('' for the empty choice).
 *
 * @param {string} id
 * @returns {string}
 */
const selectText = (id) => {
    const el = document.getElementById(id);
    if (!el || !el.value || el.selectedIndex < 0) {
        return '';
    }
    return el.options[el.selectedIndex].text.trim();
};

/**
 * Value of a text field.
 *
 * @param {string} id
 * @returns {string}
 */
const value = (id) => {
    const el = document.getElementById(id);
    return el ? el.value.trim() : '';
};

/**
 * Plain text of the course summary (TinyMCE when it is running, else the textarea).
 *
 * @returns {string}
 */
const summaryText = () => {
    const editor = window.tinymce && window.tinymce.get('id_summary_editor');
    let text = '';
    if (editor) {
        text = editor.getContent({format: 'text'});
    } else {
        const div = document.createElement('div');
        div.innerHTML = value('id_summary_editor');
        text = div.textContent;
    }
    text = text.replace(/\s+/g, ' ').trim();
    return text.length > 140 ? text.slice(0, 137).trimEnd() + '…' : text;
};

/**
 * The card's data, read from the form (same shape as theme_hikmah\local\catalog cards).
 *
 * @param {Object} str strings from the server
 * @returns {Object}
 */
const cardContext = (str) => {
    const category = document.querySelector('#fitem_id_category .form-autocomplete-selection [role="option"]');
    const image = document.querySelector('#fitem_id_overviewfiles_filemanager .fp-file img, '
        + '#fitem_id_overviewfiles_filemanager .fp-thumbnail img');
    const mode = selectText('id_customfield_mode');
    const price = parseFloat(value('id_customfield_price').replace(/,/g, '')) || 0;
    const currency = selectText('id_customfield_currency') || 'PKR';
    let startdate = '';
    const day = value('id_startdate_day');
    const month = value('id_startdate_month');
    const year = value('id_startdate_year');
    if (day && month && year) {
        const date = new Date(Number(year), Number(month) - 1, Number(day));
        startdate = str.startson.replace('{date}', date.toLocaleDateString('en-GB', {day: 'numeric', month: 'short'}));
    }
    const escape = (text) => text.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
    return {
        id: 0,
        url: '#',
        fullname: escape(value('id_fullname') || str.untitled),
        summary: summaryText(),
        category: category ? category.textContent.replace(/^\s*×\s*/, '').trim() : '',
        image: image && image.src && !/\/(f|icon)\//.test(image.src) ? image.src : null,
        hue: 200,
        mode: mode,
        islive: mode.toLowerCase() === 'live',
        language: selectText('id_customfield_language'),
        teachers: '',
        hasteachers: false,
        startdate: startdate,
        isfree: price <= 0,
        pricelabel: price <= 0 ? str.free : `${currency} ${price.toLocaleString('en-US')}`,
        pricecurrency: currency,
        priceamount: price.toLocaleString('en-US'),
        status: null,
    };
};

/**
 * Keep the preview card in step with the form.
 *
 * @param {HTMLElement} form
 * @param {HTMLElement} target where the card goes
 * @param {Object} str
 */
const setupPreview = (form, target, str) => {
    let last = '';
    let timer = null;
    const render = () => {
        const context = cardContext(str);
        const key = JSON.stringify(context);
        if (key === last) {
            return;
        }
        last = key;
        Templates.renderForPromise('theme_hikmah/course_card', context)
            .then(({html, js}) => {
                Templates.replaceNodeContents(target, html, js);
                // The card's scroll reveal is for the catalog page; here it shows at once.
                target.querySelectorAll('[data-hk-reveal]').forEach((el) => el.removeAttribute('data-hk-reveal'));
                return null;
            })
            .catch(() => null);
    };
    const later = () => {
        clearTimeout(timer);
        timer = setTimeout(render, 250);
    };
    form.addEventListener('input', later);
    form.addEventListener('change', later);
    // The summary editor, the category picker and the image picker change without form events.
    setInterval(render, 1500);
    render();
};

/**
 * Highlight the step in view.
 *
 * @param {HTMLElement[]} sections
 * @param {HTMLElement} nav
 */
const setupScrollSpy = (sections, nav) => {
    if (!('IntersectionObserver' in window)) {
        return;
    }
    const observer = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
            if (entry.isIntersecting) {
                nav.querySelectorAll('a').forEach((a) => {
                    const current = a.hash === '#' + entry.target.id;
                    a.classList.toggle('is-current', current);
                    if (current) {
                        a.setAttribute('aria-current', 'step');
                    } else {
                        a.removeAttribute('aria-current');
                    }
                });
            }
        });
    }, {rootMargin: '-30% 0px -60% 0px'});
    sections.forEach((section) => observer.observe(section));
};

/**
 * Arrange the course form into steps.
 *
 * @param {Object} str strings and step titles from the server
 */
export const init = (str) => {
    const form = document.querySelector('#region-main form.mform');
    if (!form || form.querySelector('.hk-cf') || !document.getElementById('id_general')) {
        return;
    }
    const all = Array.from(form.querySelectorAll(':scope > fieldset'));
    const catalog = fieldsetOf('#fitem_id_customfield_mode');
    const certificate = fieldsetOf('#fitem_id_customfield_certgrade');
    const groups = {
        basics: BASICS.map((id) => document.getElementById(id)).filter(Boolean),
        catalog: catalog && catalog !== certificate ? [catalog] : [],
        certificate: certificate ? [certificate] : [],
    };
    const used = [...groups.basics, ...groups.catalog, ...groups.certificate];
    groups.advanced = all.filter((fieldset) => !used.includes(fieldset));
    // The course ID number is for imports and reports, not for people: it goes to Advanced.
    const idnumber = document.getElementById('fitem_id_idnumber');
    const firstadvanced = groups.advanced[0] && groups.advanced[0].querySelector('.fcontainer');
    if (idnumber && firstadvanced) {
        firstadvanced.prepend(idnumber);
    }

    const layout = document.createElement('div');
    layout.className = 'hk-cf';
    // In place before any fieldset moves into it.
    all[0].before(layout);
    const nav = document.createElement('nav');
    nav.className = 'hk-cf__steps';
    nav.setAttribute('aria-label', str.stepsnav);
    const list = document.createElement('ol');
    nav.append(list);
    const main = document.createElement('div');
    main.className = 'hk-cf__main';
    const sections = [];
    let number = 0;
    Object.entries(groups).forEach(([key, fieldsets]) => {
        if (!fieldsets.length) {
            return;
        }
        number++;
        const [title, lead] = str.steps[key];
        const section = document.createElement('section');
        section.className = `hk-cf__step hk-cf__step--${key}`;
        section.id = `hk-step-${key}`;
        section.setAttribute('aria-labelledby', `hk-step-${key}-title`);
        section.innerHTML = `<header class="hk-cf__head"><span class="hk-cf__num" aria-hidden="true">${number}</span>`
            + `<div><h3 id="hk-step-${key}-title" class="hk-cf__title"></h3><p class="hk-cf__lead"></p></div></header>`;
        section.querySelector('.hk-cf__title').textContent = title;
        section.querySelector('.hk-cf__lead').textContent = lead;
        fieldsets.forEach((fieldset) => {
            if (key !== 'advanced') {
                // One open card per step: its sections are always shown, their own headings are hidden.
                fieldset.classList.add('hk-cf__open');
                fieldset.querySelectorAll('.fcontainer.collapse').forEach((c) => c.classList.add('show'));
                fieldset.classList.remove('collapsed');
            }
            section.append(fieldset);
        });
        main.append(section);
        sections.push(section);
        const item = document.createElement('li');
        item.innerHTML = `<a href="#hk-step-${key}"><span class="hk-cf__num" aria-hidden="true">${number}</span>`
            + '<span class="hk-cf__steplabel"></span></a>';
        item.querySelector('.hk-cf__steplabel').textContent = title;
        list.append(item);
    });

    const aside = document.createElement('aside');
    aside.className = 'hk-cf__preview';
    aside.setAttribute('aria-labelledby', 'hk-cf-preview-title');
    aside.innerHTML = '<div class="hk-cf__preview-inner"><h3 id="hk-cf-preview-title" class="hk-cf__preview-title"></h3>'
        + '<p class="hk-cf__preview-lead"></p><div class="hk-cf__card hk-catalog"></div></div>';
    aside.querySelector('.hk-cf__preview-title').textContent = str.preview;
    aside.querySelector('.hk-cf__preview-lead').textContent = str.previewlead;

    // Below 1200px the preview opens from a button instead of sitting beside the form.
    const toggle = document.createElement('button');
    toggle.type = 'button';
    toggle.className = 'btn btn-outline-secondary hk-cf__preview-toggle';
    toggle.textContent = str.previewbutton;
    toggle.setAttribute('aria-expanded', 'false');
    toggle.addEventListener('click', () => {
        const open = aside.classList.toggle('is-open');
        toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
    });
    nav.append(toggle);

    layout.append(nav, main, aside);
    form.classList.add('hk-cf-form');
    document.body.classList.add('hk-courseform');

    setupScrollSpy(sections, nav);
    setupPreview(form, aside.querySelector('.hk-cf__card'), str);
};
